// DOWSIL 795 Structural Glazing Sealant
// Ultimate elongation: 400% to 600%
const JOINT_WIDTH_MM = 20;       // mm (design joint width)
const ELONG_LIMIT    = 400;      // % (conservative limit)
const ALARM_THRESHOLD = 320;     // % (trigger alarm at 80% of limit)

const sensors = [
  { id: 'SNS-F01-N', zone: 'North', floor: 1 },
  { id: 'SNS-F03-E', zone: 'East',  floor: 3 },
  { id: 'SNS-F05-S', zone: 'South', floor: 5 },
  { id: 'SNS-F07-W', zone: 'West',  floor: 7 },
];

function rnd(min, max) {
  return parseFloat((Math.random() * (max - min) + min).toFixed(2));
}

const now = new Date();

// Temperature: realistic outdoor building facade temp
const hourAngle = (now.getHours() + now.getMinutes()/60) / 24 * 2 * Math.PI;
const baseTempC  = 28 + 12 * Math.sin(hourAngle - Math.PI/2); // diurnal cycle

const readings = sensors.map(s => {
  const tempC      = rnd(Math.max(15, baseTempC - 5), Math.min(50, baseTempC + 5));
  const tempFactor = (tempC - 15) / 35;         // normalise 15-50°C → 0-1
  const dispMm     = rnd(Math.max(0.5, 5 * tempFactor - 1), Math.min(11, 5 * tempFactor + 2));
  const elongPct   = parseFloat(((dispMm / JOINT_WIDTH_MM) * 100).toFixed(1));
  const alarmFlag  = elongPct > ALARM_THRESHOLD;

  return {
    sensorId:    s.id,
    zone:        s.zone,
    floor:       s.floor,
    timestamp:   now.toISOString(),
    temperature: tempC,
    displacement: dispMm,
    elongation:  elongPct,
    alarmFlag:   alarmFlag,
    jointWidthMm: JOINT_WIDTH_MM,
    elongLimitPct: ELONG_LIMIT
  };
});

// Primary reading for chart (first sensor or average)
const primary = readings[0];
msg.payload  = primary;
msg.topic    = 'facade/joint/data';
msg.readings = readings;   // all sensors

return msg;

// DOWSIL 795 limits
// Ultimate elongation: 400%-600% → design safe limit: 400%
// Alarm at 80% of limit = 320%

const data = msg.payload;
const ALARM_ELONG   = 320;   // %
const ALERT_ELONG   = 200;   // % - caution
const ALARM_TEMP    = 45;    // °C

if (!data || data.elongation === undefined) return null;

let alarmLevel = 'OK';
let alarmMsg   = '';

if (data.elongation > ALARM_ELONG) {
  alarmLevel = 'ALARM';
  alarmMsg   = `CRITICAL: Sensor ${data.sensorId} - Elongation ${data.elongation}% exceeds safe design threshold (${ALARM_ELONG}%). Design limit: 400%. Immediate inspection required!`;
} else if (data.elongation > ALERT_ELONG) {
  alarmLevel = 'CAUTION';
  alarmMsg   = `CAUTION: Sensor ${data.sensorId} - Elongation ${data.elongation}% above monitoring threshold.`;
} else if (data.temperature > ALARM_TEMP) {
  alarmLevel = 'TEMP_HIGH';
  alarmMsg   = `HIGH TEMP: Sensor ${data.sensorId} - Temperature ${data.temperature}°C. Check sealant thermal performance.`;
}

if (alarmLevel !== 'OK') {
  msg.payload = {
    level:    alarmLevel,
    message:  alarmMsg,
    sensor:   data.sensorId,
    zone:     data.zone,
    floor:    data.floor,
    timestamp: data.timestamp,
    values: {
      temperature:  data.temperature,
      displacement: data.displacement,
      elongation:   data.elongation
    }
  };
  msg.topic = 'facade/joint/alarm';
  return msg;
}
return null;

// Prepare data for ui-chart dual-axis display
// Left Y-axis:  Temperature (°C)
// Right Y-axis: Displacement (mm)

const data = msg.payload;
if (!data || data.temperature === undefined) return null;

const ts = new Date(data.timestamp || Date.now());
const label = ts.toLocaleTimeString('th-TH', { hour: '2-digit', minute: '2-digit', second: '2-digit' });

// Chart.js dual-axis format via ui-template
const point = {
  label:        label,
  temperature:  data.temperature,
  displacement: data.displacement,
  elongation:   data.elongation,
  sensorId:     data.sensorId,
  alarmFlag:    data.alarmFlag
};

msg.payload = point;
msg.topic   = 'chartPoint';
return msg;
